10:   State<NewsListPage> createState() => _NewsListPageState();
11: }
12: 
13: class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
14:   static final _tween = Tween<double>(begin: 0.25, end: 1);
15: 
16:   late Future<List<NewsModel>> _newsListFuture;
17: 
18:   late final AnimationController _scaleController;
